export function getCellsAndProofs(blobBundles: fulu.BlobAndProofV2[]): {cells: Uint8Array[]; proofs: Uint8Array[]}[] {
  return blobBundles.map(({blob, proofs}) => {
    const cells = kzg.computeCells(blob);
    return {cells, proofs};
  });
}

